/// <summary>
/// Do not allow record deletion if it's already saved to avoid downstream issues
/// Users must update the To date on the record instead.
/// </summary>
/// <param name = "_enableDeleteButton"></param>
public void doActiveButtons(boolean _enableDeleteButton)
{
    next doActiveButtons(_enableDeleteButton);
    GUPVendPriceAdmTrans_ds.allowDelete(!_enableDeleteButton);
}
